import React, { useState } from 'react';
import { useNavigate } from 'umi';
import { Avatar, TagBadge, RoleBadge, PostCard, Loading } from '@/components/forum';
import { timeAgo } from '@/utils/forum';
import { forumAPI } from '@/services/forum-api';
import type { Post } from '@/types';

const MOCK_POSTS: Post[] = [
  {
    id: 1,
    title: 'Làm thế nào để hiểu Recursion trong lập trình?',
    content: 'Mình đang học về đệ quy nhưng không hiểu cách hoạt động...',
    author: { id: 1, username: 'sv_tranminh', email: 'minh@student.edu.vn', role: 'student' },
    tags: [{ id: 1, name: 'Lập trình', color: '#4F8CFF', usageCount: 45 }],
    votes: 24,
    commentCount: 8,
    views: 312,
    createdAt: new Date(Date.now() - 3 * 24 * 60 * 60 * 1000).toISOString(),
  },
];

interface ProfileFormState {
  username: string;
  bio: string;
  email: string;
}

interface PasswordFormState {
  current: string;
  newpw: string;
  confirm: string;
}

export default function ProfilePage() {
  const navigate = useNavigate();
  const [tab, setTab] = useState<'posts' | 'saved' | 'settings' | 'password'>('posts');
  const [posts, setPosts] = useState<Post[]>(MOCK_POSTS);
  const [form, setForm] = useState<ProfileFormState>({
    username: 'sv_tranminh',
    bio: 'Sinh viên năm 2, đam mê lập trình',
    email: 'minh@student.edu.vn',
  });
  const [pwForm, setPwForm] = useState<PasswordFormState>({
    current: '',
    newpw: '',
    confirm: '',
  });
  const [loading, setLoading] = useState(false);
  const [toasts, setToasts] = useState<any[]>([]);

  const addToast = (message: string, type = 'info') => {
    setToasts((p) => [...p, { message, type }]);
    setTimeout(() => setToasts((p) => p.slice(1)), 3000);
  };

  const handleSave = async () => {
    setLoading(true);
    try {
      await forumAPI.updatePost(1, form);
      addToast('Đã cập nhật hồ sơ!', 'success');
    } catch (e) {
      addToast('Đã cập nhật hồ sơ! (mock)', 'success');
    }
    setLoading(false);
  };

  const handleChangePw = async () => {
    if (pwForm.newpw !== pwForm.confirm) {
      addToast('Mật khẩu xác nhận không khớp', 'error');
      return;
    }
    if (pwForm.newpw.length < 6) {
      addToast('Mật khẩu phải ít nhất 6 ký tự', 'error');
      return;
    }
    setLoading(true);
    try {
      await forumAPI.createPost({ title: '', content: '', tags: [] });
      addToast('Đã đổi mật khẩu thành công!', 'success');
    } catch (e) {
      addToast('Đã đổi mật khẩu thành công! (mock)', 'success');
    }
    setPwForm({ current: '', newpw: '', confirm: '' });
    setLoading(false);
  };

  const user = { id: 1, username: 'sv_tranminh', email: form.email, role: 'student' };

  return (
    <div className="page">
      <div className="profile-header">
        <Avatar username={user.username} />
        <div style={{ flex: 1 }}>
          <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: 24 }}>{user.username}</div>
          <div style={{ marginTop: 4 }}>
            <RoleBadge role={user.role || 'student'} />
          </div>
          <div style={{ color: 'var(--muted)', fontSize: 14, marginTop: 8 }}>{user.email}</div>
          <div style={{ display: 'flex', gap: 24, marginTop: 16 }}>
            <div>
              <div style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: 20 }}>12</div>
              <div style={{ fontSize: 13, color: 'var(--muted)' }}>Bài viết</div>
            </div>
            <div>
              <div style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: 20 }}>48</div>
              <div style={{ fontSize: 13, color: 'var(--muted)' }}>Bình luận</div>
            </div>
            <div>
              <div style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: 20 }}>234</div>
              <div style={{ fontSize: 13, color: 'var(--muted)' }}>Vote nhận</div>
            </div>
          </div>
        </div>
      </div>

      <div className="profile-tab-bar">
        {['posts', 'saved', 'settings', 'password'].map((t: string) => (
          <div
            key={t}
            className={`tab-item ${tab === t ? 'active' : ''}`}
            onClick={() => setTab(t as any)}
          >
            {t === 'posts'
              ? '📝 Bài viết'
              : t === 'saved'
              ? '🔖 Đã lưu'
              : t === 'settings'
              ? '⚙️ Hồ sơ'
              : '🔒 Mật khẩu'}
          </div>
        ))}
      </div>

      {tab === 'posts' && (
        <div className="stack">
          {posts.map((p) => (
            <PostCard key={p.id} post={p} onClick={() => navigate(`/forum/${p.id}`)} />
          ))}
        </div>
      )}

      {tab === 'saved' && (
        <div className="stack">
          {posts.slice(0, 2).map((p) => (
            <PostCard key={p.id} post={p} onClick={() => navigate(`/forum/${p.id}`)} />
          ))}
        </div>
      )}

      {tab === 'settings' && (
        <div className="card" style={{ maxWidth: 560 }}>
          <div style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: 18, marginBottom: 24 }}>
            Thông tin cá nhân
          </div>
          <div className="form-group">
            <label className="form-label">Tên đăng nhập</label>
            <input
              className="form-input"
              value={form.username}
              onChange={(e) => setForm((p) => ({ ...p, username: e.target.value }))}
            />
          </div>
          <div className="form-group">
            <label className="form-label">Email</label>
            <input
              className="form-input"
              type="email"
              value={form.email}
              onChange={(e) => setForm((p) => ({ ...p, email: e.target.value }))}
            />
          </div>
          <div className="form-group">
            <label className="form-label">Giới thiệu bản thân</label>
            <textarea
              className="form-textarea"
              style={{ minHeight: 100 }}
              placeholder="Mô tả ngắn về bản thân..."
              value={form.bio}
              onChange={(e) => setForm((p) => ({ ...p, bio: e.target.value }))}
            />
          </div>
          <button className="btn btn-primary" onClick={handleSave} disabled={loading}>
            {loading ? 'Đang lưu...' : '💾 Lưu thay đổi'}
          </button>
        </div>
      )}

      {tab === 'password' && (
        <div className="card" style={{ maxWidth: 480 }}>
          <div style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: 18, marginBottom: 24 }}>
            Đổi mật khẩu
          </div>
          <div className="form-group">
            <label className="form-label">Mật khẩu hiện tại</label>
            <input
              className="form-input"
              type="password"
              value={pwForm.current}
              onChange={(e) => setPwForm((p) => ({ ...p, current: e.target.value }))}
            />
          </div>
          <div className="form-group">
            <label className="form-label">Mật khẩu mới</label>
            <input
              className="form-input"
              type="password"
              value={pwForm.newpw}
              onChange={(e) => setPwForm((p) => ({ ...p, newpw: e.target.value }))}
            />
          </div>
          <div className="form-group">
            <label className="form-label">Xác nhận mật khẩu mới</label>
            <input
              className="form-input"
              type="password"
              value={pwForm.confirm}
              onChange={(e) => setPwForm((p) => ({ ...p, confirm: e.target.value }))}
            />
          </div>
          <button className="btn btn-primary" onClick={handleChangePw} disabled={loading}>
            {loading ? 'Đang lưu...' : '🔒 Đổi mật khẩu'}
          </button>
        </div>
      )}

      {toasts.map((t, i) => (
        <div key={i} className={`toast toast-${t.type}`}>
          {t.message}
        </div>
      ))}
    </div>
  );
}

admin/index.__content:
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'umi';
import { Avatar, TagBadge, RoleBadge, PostCard } from '@/components/forum';
import { timeAgo } from '@/utils/forum';
import { forumAPI } from '@/services/forum-api';
import type { Post, User, Tag } from '@/types';

const MOCK_POSTS: Post[] = [
  {
    id: 1,
    title: 'Làm thế nào để hiểu Recursion?',
    content: 'Mình đang học về đệ quy...',
    author: { id: 1, username: 'sv_tranminh', email: 'minh@student.edu.vn', role: 'student' },
    tags: [{ id: 1, name: 'Lập trình', color: '#4F8CFF', usageCount: 45 }],
    votes: 24,
    commentCount: 8,
    views: 312,
    createdAt: new Date(Date.now() - 3 * 24 * 60 * 60 * 1000).toISOString(),
  },
];

const MOCK_USERS: User[] = [
  { id: 1, username: 'sv_tranminh', email: 'minh@student.edu.vn', role: 'student', isActive: true },
  { id: 2, username: 'gv_nguyenha', email: 'ha@teacher.edu.vn', role: 'lecturer', isActive: true },
  { id: 3, username: 'admin', email: 'admin@forum.edu.vn', role: 'admin', isActive: true },
];

const MOCK_TAGS: Tag[] = [
  { id: 1, name: 'Lập trình', color: '#4F8CFF', usageCount: 45 },
  { id: 2, name: 'React', color: '#61DAFB', usageCount: 38 },
  { id: 3, name: 'SQL', color: '#4DE2E2', usageCount: 28 },
];

export default function AdminPage() {
  const navigate = useNavigate();
  const [menu, setMenu] = useState<'dashboard' | 'users' | 'posts' | 'tags'>('dashboard');
  const [users, setUsers] = useState<User[]>(MOCK_USERS);
  const [posts, setPosts] = useState<Post[]>(MOCK_POSTS);
  const [editUser, setEditUser] = useState<User | null>(null);
  const [modal, setModal] = useState<string | null>(null);
  const [toasts, setToasts] = useState<any[]>([]);

  const addToast = (message: string, type = 'info') => {
    setToasts((p) => [...p, { message, type }]);
    setTimeout(() => setToasts((p) => p.slice(1)), 3000);
  };

  useEffect(() => {
    (async () => {
      try {
        const ru = await forumAPI.getPosts();
        const rp = await forumAPI.getPosts();
        if (ru?.data) setUsers(ru.data);
        if (rp?.data) setPosts(rp.data);
      } catch (e) {
        console.log('Using mock data');
      }
    })();
  }, []);

  const handleDeletePost = async (id: number) => {
    if (!confirm('Xóa bài viết này?')) return;
    try {
      await forumAPI.deletePost(id);
      setPosts((p) => p.filter((x) => x.id !== id));
      addToast('Đã xóa bài viết', 'success');
    } catch (e) {
      setPosts((p) => p.filter((x) => x.id !== id));
    }
  };

  const handleDeleteUser = async (id: number) => {
    if (!confirm('Xóa người dùng này?')) return;
    try {
      await forumAPI.deletePost(id);
      setUsers((p) => p.filter((u) => u.id !== id));
      addToast('Đã xóa người dùng', 'success');
    } catch (e) {
      setUsers((p) => p.filter((u) => u.id !== id));
    }
  };

  const MENU_ITEMS = [
    { id: 'dashboard', icon: '📊', label: 'Dashboard' },
    { id: 'users', icon: '👥', label: 'Người dùng' },
    { id: 'posts', icon: '📝', label: 'Bài viết' },
    { id: 'tags', icon: '🏷️', label: 'Tags' },
  ];

  const barData = [
    { label: 'T2', v: 18 },
    { label: 'T3', v: 32 },
    { label: 'T4', v: 24 },
    { label: 'T5', v: 45 },
    { label: 'T6', v: 38 },
    { label: 'T7', v: 22 },
    { label: 'CN', v: 15 },
  ];
  const maxBar = Math.max(...barData.map((d) => d.v));

  return (
    <div className="admin-layout" style={{ minHeight: '100vh' }}>
      {/* Sidebar */}
      <div className="admin-sidebar">
        <div className="admin-logo">📚 Admin</div>
        <div style={{ padding: '8px 12px 6px', fontSize: 11, color: 'var(--faint)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '.5px' }}>Menu</div>
        <div className="admin-menu">
          {MENU_ITEMS.map((m: any) => (
            <button key={m.id} className={`admin-menu-item ${menu === m.id ? 'active' : ''}`} onClick={() => setMenu(m.id)}>
              <span>{m.icon}</span> {m.label}
            </button>
          ))}
        </div>
        <div style={{ margin: 'auto 0 0', padding: 12 }}>
          <button className="admin-menu-item" style={{ width: '100%' }} onClick={() => navigate('/forum')}>
            ← Về diễn đàn
          </button>
        </div>
      </div>

      {/* Main */}
      <div className="admin-main">
        <div className="admin-header">
          <div style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: 18 }}>
            {MENU_ITEMS.find((m: any) => m.id === menu)?.label}
          </div>
          <div style={{ marginLeft: 'auto', display: 'flex', alignItems: 'center', gap: 12 }}>
            <Avatar username="admin" />
            <span style={{ fontSize: 14, fontWeight: 500 }}>Admin</span>
          </div>
        </div>

        <div className="admin-content">
          {/* DASHBOARD */}
          {menu === 'dashboard' && (
            <>
              <div className="stat-grid">
                {[
                  { label: 'Tổng bài viết', num: posts.length * 47, icon: '📝', color: '#4F8CFF' },
                  { label: 'Tổng người dùng', num: users.length * 23, icon: '👥', color: '#7B61FF' },
                  { label: 'Bình luận', num: posts.reduce((a, b) => a + b.commentCount, 0) * 12, icon: '💬', color: '#4DE2E2' },
                  { label: 'Hoạt động hôm nay', num: 38, icon: '🔥', color: '#F59E0B' },
                ].map((s, i) => (
                  <div key={i} className="stat-card">
                    <div style={{ float: 'right', fontSize: 32, opacity: 0.2 }}>{s.icon}</div>
                    <div className="stat-card-num" style={{ color: s.color }}>{s.num.toLocaleString()}</div>
                    <div className="stat-card-label">{s.label}</div>
                  </div>
                ))}
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 24 }}>
                <div className="card">
                  <div style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: 15, marginBottom: 16 }}>📈 Bài viết theo ngày (tuần này)</div>
                  <div className="chart-bar">
                    {barData.map((d) => (
                      <div key={d.label} className="chart-col">
                        <div className="chart-bar-fill" style={{ height: `${(d.v / maxBar) * 90}px` }} />
                        <div className="chart-label">{d.label}</div>
                        <div className="chart-label" style={{ color: 'var(--pri)' }}>{d.v}</div>
                      </div>
                    ))}
                  </div>
                </div>

                <div className="card">
                  <div style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: 15, marginBottom: 16 }}>📊 Thống kê hệ thống</div>
                  {[
                    { label: 'Tỷ lệ bài viết có câu trả lời', val: 78 },
                    { label: 'Người dùng hoạt động (7 ngày)', val: 65 },
                    { label: 'Tỷ lệ sinh viên', val: 82 },
                    { label: 'Điểm hài lòng', val: 91 },
                  ].map((s, i) => (
                    <div key={i} style={{ marginBottom: 14 }}>
                      <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 13, marginBottom: 4 }}>
                        <span className="text-muted">{s.label}</span>
                        <span style={{ fontWeight: 600, color: 'var(--pri)' }}>{s.val}%</span>
                      </div>
                      <div className="progress-bar">
                        <div className="progress-fill" style={{ width: `${s.val}%` }} />
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              <div className="card mt-6">
                <div style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: 15, marginBottom: 16 }}>📋 Bài viết gần đây</div>
                <table className="data-table">
                  <thead>
                    <tr><th>Tiêu đề</th><th>Tác giả</th><th>Vote</th><th>Views</th><th>Ngày đăng</th></tr>
                  </thead>
                  <tbody>
                    {posts.slice(0, 5).map((p) => (
                      <tr key={p.id}>
                        <td style={{ maxWidth: 280 }}><div style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{p.title}</div></td>
                        <td><div className="flex items-center gap-2"><Avatar username={p.author.username} />{p.author.username}</div></td>
                        <td><span className="badge badge-blue">▲ {p.votes}</span></td>
                        <td>{p.views}</td>
                        <td>{timeAgo(p.createdAt)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </>
          )}

          {/* USERS */}
          {menu === 'users' && (
            <div className="card">
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
                <div style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: 16 }}>👥 Quản lý người dùng ({users.length})</div>
                <button className="btn btn-primary btn-sm" onClick={() => setModal('adduser')}>+ Thêm người dùng</button>
              </div>
              <div style={{ overflowX: 'auto' }}>
                <table className="data-table">
                  <thead>
                    <tr><th>Người dùng</th><th>Email</th><th>Vai trò</th><th>Trạng thái</th><th>Hành động</th></tr>
                  </thead>
                  <tbody>
                    {users.map((u) => (
                      <tr key={u.id}>
                        <td><div className="flex items-center gap-2"><Avatar username={u.username} /><span style={{ fontWeight: 500 }}>{u.username}</span></div></td>
                        <td>{u.email}</td>
                        <td><RoleBadge role={u.role} /></td>
                        <td><span className={`badge ${u.isActive ? 'badge-green' : 'badge-red'}`}>{u.isActive ? '✓ Hoạt động' : '✗ Đã khóa'}</span></td>
                        <td><div className="flex gap-2">
                          <button className="btn btn-ghost btn-xs" onClick={() => { setEditUser(u); setModal('edituser'); }}>Sửa</button>
                          {u.role !== 'admin' && <button className="btn btn-danger btn-xs" onClick={() => handleDeleteUser(u.id)}>Xóa</button>}
                        </div></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* POSTS */}
          {menu === 'posts' && (
            <div className="card">
              <div style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: 16, marginBottom: 20 }}>📝 Quản lý bài viết ({posts.length})</div>
              <div style={{ overflowX: 'auto' }}>
                <table className="data-table">
                  <thead>
                    <tr><th>Tiêu đề</th><th>Tác giả</th><th>Tags</th><th>Vote</th><th>Views</th><th>Ngày đăng</th><th>Hành động</th></tr>
                  </thead>
                  <tbody>
                    {posts.map((p) => (
                      <tr key={p.id}>
                        <td style={{ maxWidth: 240 }}><div style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', fontWeight: 500, cursor: 'pointer', color: 'var(--pri)' }} onClick={() => navigate(`/forum/${p.id}`)}>{p.title}</div></td>
                        <td>{p.author.username}</td>
                        <td><div className="flex" style={{ gap: 4, flexWrap: 'wrap' }}>{p.tags.slice(0, 2).map((t) => <TagBadge key={t.id} tag={t} />)}{p.tags.length > 2 && <span className="text-sm text-muted">+{p.tags.length - 2}</span>}</div></td>
                        <td><span className="badge badge-blue">▲ {p.votes}</span></td>
                        <td>{p.views}</td>
                        <td>{timeAgo(p.createdAt)}</td>
                        <td><div className="flex gap-2"><button className="btn btn-ghost btn-xs" onClick={() => navigate(`/forum/${p.id}`)}>Xem</button><button className="btn btn-danger btn-xs" onClick={() => handleDeletePost(p.id)}>Xóa</button></div></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* TAGS */}
          {menu === 'tags' && (
            <div className="card">
              <div style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: 16, marginBottom: 20 }}>🏷️ Quản lý Tags</div>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: 14 }}>
                {MOCK_TAGS.map((t) => (
                  <div key={t.id} style={{ border: '1px solid var(--border)', borderRadius: 'var(--radius-sm)', padding: 16 }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                      <TagBadge tag={t} />
                      <button className="btn btn-ghost btn-xs">Xóa</button>
                    </div>
                    <div style={{ marginTop: 10, fontSize: 13, color: 'var(--muted)' }}>{t.usageCount} bài viết</div>
                    <div className="progress-bar mt-4"><div className="progress-fill" style={{ width: `${Math.min(100, (t.usageCount / 55) * 100)}%`, background: t.color }} /></div>
                  </div>
                ))}
                <div style={{ border: '2px dashed var(--border)', borderRadius: 'var(--radius-sm)', padding: 16, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: 'var(--muted)', flexDirection: 'column', gap: 8 }} onClick={() => setModal('addtag')}>
                  <span style={{ fontSize: 28 }}>+</span>
                  <span style={{ fontSize: 13 }}>Thêm tag mới</span>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Modals */}
      {modal && (
        <div className="modal-overlay" onClick={(e) => e.target === e.currentTarget && setModal(null)}>
          <div className="modal">
            {modal === 'edituser' && editUser && (
              <>
                <div className="modal-title">✏️ Sửa người dùng: {editUser.username}</div>
                <div className="form-group">
                  <label className="form-label">Vai trò</label>
                  <select className="form-select" value={editUser.role} onChange={(e) => setEditUser((p) => ({ ...p!, role: e.target.value as any }))}>
                    <option value="student">Sinh viên</option>
                    <option value="lecturer">Giảng viên</option>
                    <option value="admin">Quản trị viên</option>
                  </select>
                </div>
                <div className="form-group">
                  <label className="form-label">Trạng thái</label>
                  <div className="flex items-center gap-2">
                    <input type="checkbox" checked={editUser.isActive} onChange={(e) => setEditUser((p) => ({ ...p!, isActive: e.target.checked }))} />
                    <span style={{ fontSize: 14 }}>Tài khoản đang hoạt động</span>
                  </div>
                </div>
                <div className="modal-actions">
                  <button className="btn btn-ghost" onClick={() => setModal(null)}>Hủy</button>
                  <button className="btn btn-primary" onClick={async () => { addToast('Đã cập nhật người dùng!', 'success'); setModal(null); }}>Lưu thay đổi</button>
                </div>
              </>
            )}
            {modal === 'adduser' && (
              <>
                <div className="modal-title">➕ Thêm người dùng mới</div>
                <div className="form-group"><label className="form-label">Tên đăng nhập</label><input className="form-input" placeholder="Tên đăng nhập" /></div>
                <div className="form-group"><label className="form-label">Email</label><input className="form-input" type="email" placeholder="Email" /></div>
                <div className="form-group"><label className="form-label">Vai trò</label><select className="form-select"><option value="student">Sinh viên</option><option value="lecturer">Giảng viên</option><option value="admin">Quản trị viên</option></select></div>
                <div className="modal-actions"><button className="btn btn-ghost" onClick={() => setModal(null)}>Hủy</button><button className="btn btn-primary" onClick={() => { addToast('Đã thêm người dùng!', 'success'); setModal(null); }}>Thêm</button></div>
              </>
            )}
            {modal === 'addtag' && (
              <>
                <div className="modal-title">🏷️ Thêm Tag mới</div>
                <div className="form-group"><label className="form-label">Tên tag</label><input className="form-input" placeholder="VD: Lập trình" /></div>
                <div className="form-group"><label className="form-label">Màu sắc</label><div className="flex items-center gap-3"><input type="color" defaultValue="#4F8CFF" style={{ width: 48, height: 40, border: '1px solid var(--border)', borderRadius: 6, cursor: 'pointer' }} /><span style={{ fontSize: 14, color: 'var(--muted)' }}>Chọn màu cho tag</span></div></div>
                <div className="modal-actions"><button className="btn btn-ghost" onClick={() => setModal(null)}>Hủy</button><button className="btn btn-primary" onClick={() => { addToast('Đã thêm tag!', 'success'); setModal(null); }}>Thêm tag</button></div>
              </>
            )}
          </div>
        </div>
      )}

      {toasts.map((t, i) => (
        <div key={i} className={`toast toast-${t.type}`}>{t.message}</div>
      ))}
    </div>
  );
}

forum/index.__content:
import React, { useState, useEffect } from 'react';
import { history } from 'umi';
import { Avatar, TagBadge, RoleBadge, PostCard, Loading, EmptyState } from '@/components/forum';
import { timeAgo } from '@/utils/forum';
import { forumAPI } from '@/services/forum-api';
import { useAuth } from '@/hooks/useAuth';
import type { Post, Tag, User } from '@/types';

// Mock data
const MOCK_POSTS: Post[] = [
  {
    id: 1,
    title: 'Làm thế nào để hiểu Recursion trong lập trình?',
    content: 'Mình đang học về đệ quy nhưng không hiểu cách hoạt động. Ai có thể giải thích bằng ví dụ thực tế không?',
    author: { id: 1, username: 'sv_tranminh', role: 'student', avatar: null },
    tags: [
      { id: 1, name: 'Lập trình', color: '#4F8CFF' },
      { id: 2, name: 'Thuật toán', color: '#7B61FF' },
    ],
    votes: 24,
    views: 312,
    commentCount: 8,
    createdAt: '2024-05-20T10:30:00Z',
  },
  {
    id: 2,
    title: '"Phân biệt giữa SQL JOIN các loại: INNER, LEFT, RIGHT, FULL"',
    content: 'Mình hay bị nhầm lẫn giữa các loại JOIN trong SQL. Ai giải thích rõ ràng với ví dụ được không?',
    author: { id: 2, username: 'gv_nguyenha', role: 'lecturer', avatar: null },
    tags: [
      { id: 3, name: 'Cơ sở dữ liệu', color: '#4DE2E2' },
      { id: 4, name: 'SQL', color: '#22C55E' },
    ],
    votes: 41,
    views: 580,
    commentCount: 15,
    createdAt: '2024-05-19T14:20:00Z',
  },
  {
    id: 3,
    title: 'Hướng dẫn setup môi trường React từ đầu năm 2024',
    content: 'Mình mới học React và muốn biết cách setup môi trường đúng chuẩn hiện tại không dùng CRA nữa.',
    author: { id: 3, username: 'sv_lephuong', role: 'student', avatar: null },
    tags: [
      { id: 5, name: 'React', color: '#61DAFB' },
      { id: 6, name: 'Frontend', color: '#FF6B6B' },
    ],
    votes: 18,
    views: 201,
    commentCount: 5,
    createdAt: '2024-05-18T09:15:00Z',
  },
  {
    id: 4,
    title: 'Giải thích Big O notation cho người mới',
    content: 'Mình nghe nhiều về Big O nhưng không hiểu tại sao nó quan trọng và cách tính như thế nào.',
    author: { id: 4, username: 'sv_dohung', role: 'student', avatar: null },
    tags: [
      { id: 1, name: 'Lập trình', color: '#4F8CFF' },
      { id: 2, name: 'Thuật toán', color: '#7B61FF' },
    ],
    votes: 32,
    views: 445,
    commentCount: 12,
    createdAt: '2024-05-17T16:45:00Z',
  },
  {
    id: 5,
    title: 'Tổng hợp các lệnh Git quan trọng cần nhớ',
    content: 'Chia sẻ cheatsheet các lệnh Git hay dùng nhất trong quá trình làm việc nhóm.',
    author: { id: 2, username: 'gv_nguyenha', role: 'lecturer', avatar: null },
    tags: [
      { id: 7, name: 'Git', color: '#F05033' },
      { id: 8, name: 'DevOps', color: '#FF9800' },
    ],
    votes: 55,
    views: 720,
    commentCount: 20,
    createdAt: '2024-05-16T11:00:00Z',
  },
];

const MOCK_TAGS: Tag[] = [
  { id: 1, name: 'Lập trình', color: '#4F8CFF' },
  { id: 2, name: 'Thuật toán', color: '#7B61FF' },
  { id: 3, name: 'Cơ sở dữ liệu', color: '#4DE2E2' },
  { id: 4, name: 'SQL', color: '#22C55E' },
  { id: 5, name: 'React', color: '#61DAFB' },
  { id: 6, name: 'Frontend', color: '#FF6B6B' },
  { id: 7, name: 'Git', color: '#F05033' },
  { id: 8, name: 'DevOps', color: '#FF9800' },
];

const MOCK_USERS: User[] = [
  { id: 1, username: 'sv_tranminh', email: 'tranminh@student.edu.vn', role: 'student', avatar: null },
  { id: 2, username: 'gv_nguyenha', email: 'nguyenha@edu.vn', role: 'lecturer', avatar: null },
  { id: 3, username: 'sv_lephuong', email: 'lephuong@student.edu.vn', role: 'student', avatar: null },
];

export default function HomePage() {
  const { user } = useAuth();
  const [posts, setPosts] = useState<Post[]>(MOCK_POSTS);
  const [tags, setTags] = useState<Tag[]>(MOCK_TAGS);
  const [loading, setLoading] = useState(false);
  const [filter, setFilter] = useState('newest');
  const [activeTag, setActiveTag] = useState<string | null>(null);
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);

  useEffect(() => {
    (async () => {
      setLoading(true);
      try {
        const params: any = { page, limit: 10 };
        if (filter !== 'newest') params.sort = filter;
        if (activeTag) params.tag = activeTag;
        if (search) params.keyword = search;

        const res = await forumAPI.getPosts(params);
        if (res?.data) setPosts(res.data);

        const tagsRes = await forumAPI.getTags();
        if (tagsRes?.data) setTags(tagsRes.data);
      } catch (err) {
        // Use mock data on error
        setPosts(MOCK_POSTS);
        setTags(MOCK_TAGS);
      }
      setLoading(false);
    })();
  }, [page, filter, activeTag, search]);

  const filtered = posts.filter((p) => {
    if (search && !p.title.toLowerCase().includes(search.toLowerCase()) &&
      !p.content.toLowerCase().includes(search.toLowerCase())) return false;
    if (activeTag && !p.tags.some((t) => t.name === activeTag)) return false;
    return true;
  });

  return (
    <div className="page">
      {/* Hero */}
      <div className="hero">
        <h1>📚 Diễn đàn Hỏi Đáp<br />Sinh viên</h1>
        <p>Chia sẻ kiến thức · Giải đáp thắc mắc · Học hỏi cùng nhau</p>
        <div className="hero-btns">
          {user ? (
            <button className="btn-hero btn-hero-pri" onClick={() => history.push('/forum/ask')}>
              ✏️ Đặt câu hỏi
            </button>
          ) : (
            <>
              <button className="btn-hero btn-hero-pri" onClick={() => history.push('/auth/login')}>
                Bắt đầu ngay
              </button>
              <button className="btn-hero btn-hero-sec" onClick={() => history.push('/auth/register')}>
                Tạo tài khoản
              </button>
            </>
          )}
        </div>
        <div className="hero-stats">
          <div className="hero-stat">
            <div className="hero-stat-num">{posts.length * 47}+</div>
            <div className="hero-stat-label">Bài viết</div>
          </div>
          <div className="hero-stat">
            <div className="hero-stat-num">1,234</div>
            <div className="hero-stat-label">Thành viên</div>
          </div>
          <div className="hero-stat">
            <div className="hero-stat-num">{tags.length * 89}+</div>
            <div className="hero-stat-label">Bình luận</div>
          </div>
          <div className="hero-stat">
            <div className="hero-stat-num">{tags.length}</div>
            <div className="hero-stat-label">Chủ đề</div>
          </div>
        </div>
      </div>

      <div className="two-col">
        {/* Main */}
        <div>
          <div className="section-header">
            <div className="section-title">🔥 Bài viết mới nhất</div>
            <div style={{ display: 'flex', gap: 8 }}>
              {['newest', 'hot', 'votes', 'views'].map((s) => (
                <button
                  key={s}
                  className={`filter-btn ${filter === s ? 'active' : ''}`}
                  onClick={() => setFilter(s)}
                >
                  {s === 'newest' ? 'Mới nhất' : s === 'hot' ? 'Nổi bật' : s === 'votes' ? 'Vote cao' : 'Xem nhiều'}
                </button>
              ))}
            </div>
          </div>

          {/* Search */}
          <div className="search-wrap" style={{ maxWidth: '100%', marginBottom: 16 }}>
            <span className="search-icon">🔍</span>
            <input
              className="search-input"
              placeholder="Tìm kiếm bài viết, câu hỏi..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>

          {loading ? (
            <Loading />
          ) : filtered.length ? (
            <div className="stack">
              {filtered.map((p) => (
                <PostCard key={p.id} post={p} onClick={() => history.push(`/forum/${p.id}`)} />
              ))}
            </div>
          ) : (
            <EmptyState text="Không tìm thấy bài viết nào" />
          )}

          {/* Pagination */}
          {!loading && (
            <div className="pagination">
              {[1, 2, 3].map((p) => (
                <button
                  key={p}
                  className={`page-btn ${page === p ? 'active' : ''}`}
                  onClick={() => setPage(p)}
                >
                  {p}
                </button>
              ))}
            </div>
          )}
        </div>

        {/* Sidebar */}
        <div className="sidebar">
          {/* Tags */}
          <div className="card-sm">
            <div className="sidebar-title">🏷️ Chủ đề phổ biến</div>
            <div className="tags-wrap">
              {tags.map((t) => (
                <TagBadge
                  key={t.id}
                  tag={t}
                  active={activeTag === t.name}
                  onClick={() => setActiveTag(activeTag === t.name ? null : t.name)}
                />
              ))}
            </div>
          </div>

          {/* Top Lecturers */}
          <div className="card-sm">
            <div className="sidebar-title">👨‍🏫 Giảng viên nổi bật</div>
            {MOCK_USERS.filter((u) => u.role === 'lecturer').map((u) => (
              <div key={u.id} className="flex items-center gap-2" style={{ marginBottom: 12 }}>
                <Avatar username={u.username} avatar={u.avatar} />
                <div>
                  <div style={{ fontSize: 14, fontWeight: 500 }}>{u.username}</div>
                  <RoleBadge role={u.role} />
                </div>
              </div>
            ))}
          </div>

          {/* Hot posts */}
          <div className="card-sm">
            <div className="sidebar-title">🔥 Hot nhất tuần</div>
            {[...posts]
              .sort((a, b) => b.votes - a.votes)
              .slice(0, 3)
              .map((p) => (
                <div
                  key={p.id}
                  style={{ marginBottom: 12, cursor: 'pointer' }}
                  onClick={() => history.push(`/forum/${p.id}`)}
                >
                  <div style={{ fontSize: 13, fontWeight: 500, lineHeight: 1.4, color: 'var(--text)' }}>
                    {p.title}
                  </div>
                  <div style={{ fontSize: 12, color: 'var(--faint)', marginTop: 3 }}>
                    ▲ {p.votes} · 👁 {p.views}
                  </div>
                </div>
              ))}
          </div>
        </div>
      </div>
    </div>
  );
}

