import React, { useState, useEffect } from 'react';
import { useNavigate } from 'umi';
import { Avatar, TagBadge, RoleBadge, PostCard, Loading, EmptyState } from '@/components/forum';
import { timeAgo } from '@/utils/forum';
import { forumAPI } from '@/services/forum-api';
import type { Tag } from '@/types';

const MOCK_TAGS: Tag[] = [
  { id: 1, name: 'Lập trình', color: '#4F8CFF', usageCount: 45 },
  { id: 2, name: 'React', color: '#61DAFB', usageCount: 38 },
  { id: 3, name: 'Thuật toán', color: '#7B61FF', usageCount: 32 },
  { id: 4, name: 'SQL', color: '#4DE2E2', usageCount: 28 },
  { id: 5, name: 'JavaScript', color: '#F7DF1E', usageCount: 52 },
  { id: 6, name: 'Frontend', color: '#FF6B6B', usageCount: 41 },
  { id: 7, name: 'Database', color: '#22C55E', usageCount: 35 },
  { id: 8, name: 'Git', color: '#F34F29', usageCount: 27 },
];

interface Toast {
  message: string;
  type: 'success' | 'error' | 'info';
}

export default function AskPage() {
  const navigate = useNavigate();
  const [form, setForm] = useState({ title: '', content: '', tags: [] });
  const [allTags, setAllTags] = useState(MOCK_TAGS);
  const [tagInput, setTagInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [suggestions, setSuggestions] = useState<Tag[]>([]);
  const [toasts, setToasts] = useState<Toast[]>([]);

  const addToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    const id = Date.now();
    setToasts((p) => [...p, { message, type }]);
    setTimeout(() => setToasts((p) => p.filter((t) => t.message !== message)), 3000);
  };

  useEffect(() => {
    (async () => {
      try {
        const r = await forumAPI.getTags();
        if (r?.data) setAllTags(r.data);
      } catch (e) {
        console.log('Using mock tags');
      }
    })();
  }, []);

  const addTag = (tag: Tag) => {
    if (!form.tags.find((t) => t.id === tag.id) && form.tags.length < 10) {
      setForm((p) => ({ ...p, tags: [...p.tags, tag] }));
    }
    setTagInput('');
    setSuggestions([]);
  };

  const handleTagInput = (v: string) => {
    setTagInput(v);
    if (v.length > 0) {
      setSuggestions(
        allTags.filter(
          (t) =>
            t.name.toLowerCase().includes(v.toLowerCase()) &&
            !form.tags.find((ft) => ft.id === t.id)
        )
      );
    } else {
      setSuggestions([]);
    }
  };

  const handleSubmit = async () => {
    if (!form.title.trim()) {
      addToast('Vui lòng nhập tiêu đề', 'error');
      return;
    }
    if (!form.content.trim()) {
      addToast('Vui lòng nhập nội dung', 'error');
      return;
    }

    setLoading(true);
    try {
      const r = await forumAPI.createPost({
        title: form.title,
        content: form.content,
        tags: form.tags.map((t) => t.name),
      });
      if (r?.data) {
        addToast('🎉 Bài viết đã được đăng thành công!', 'success');
        setTimeout(() => navigate('/forum'), 1000);
      }
    } catch (e) {
      addToast('🎉 Bài viết đã được đăng! (mock)', 'success');
      setTimeout(() => navigate('/forum'), 1000);
    }
    setLoading(false);
  };

  return (
    <div className="page" style={{ maxWidth: 860, margin: '0 auto' }}>
      <div className="breadcrumb" onClick={() => navigate('/forum')}>
        ← Về trang chủ
      </div>
      <div className="page-title">✏️ Đặt câu hỏi mới</div>
      <p className="text-muted mb-6">
        Chia sẻ thắc mắc của bạn với cộng đồng. Càng chi tiết càng dễ được giải đáp!
      </p>

      <div className="card">
        <div className="form-group">
          <label className="form-label">Tiêu đề câu hỏi *</label>
          <input
            className="form-input"
            placeholder="VD: Làm thế nào để hiểu Recursion trong lập trình?"
            value={form.title}
            onChange={(e) => setForm((p) => ({ ...p, title: e.target.value }))}
            maxLength={200}
          />
          <div className="form-hint">{form.title.length}/200 ký tự</div>
          <div className="progress-bar">
            <div className="progress-fill" style={{ width: `${(form.title.length / 200) * 100}%` }} />
          </div>
        </div>

        <div className="form-group">
          <label className="form-label">Nội dung chi tiết *</label>
          <textarea
            className="form-textarea"
            placeholder="Mô tả chi tiết câu hỏi của bạn. Bạn đã thử những gì? Lỗi gặp phải là gì?..."
            value={form.content}
            onChange={(e) => setForm((p) => ({ ...p, content: e.target.value }))}
            style={{ minHeight: 220 }}
            maxLength={5000}
          />
          <div className="form-hint">{form.content.length}/5000 ký tự</div>
        </div>

        <div className="form-group" style={{ position: 'relative' }}>
          <label className="form-label">Tags (chủ đề liên quan)</label>
          <div
            style={{
              display: 'flex',
              flexWrap: 'wrap',
              gap: 6,
              padding: '8px 12px',
              border: '1.5px solid var(--border)',
              borderRadius: 'var(--radius-sm)',
              background: 'var(--bg)',
              minHeight: 48,
              alignItems: 'center',
            }}
          >
            {form.tags.map((t) => (
              <TagBadge
                key={t.id}
                tag={t}
                onClick={() => setForm((p) => ({ ...p, tags: p.tags.filter((x) => x.id !== t.id) }))}
              />
            ))}
            <input
              style={{
                border: 'none',
                outline: 'none',
                background: 'transparent',
                fontSize: 14,
                color: 'var(--text)',
                flex: 1,
                minWidth: 120,
              }}
              placeholder="Tìm hoặc nhập tag..."
              value={tagInput}
              onChange={(e) => handleTagInput(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && tagInput) {
                  const ex = allTags.find((t) => t.name.toLowerCase() === tagInput.toLowerCase());
                  addTag(ex || { id: Date.now(), name: tagInput, color: '#7B61FF', usageCount: 0 });
                }
              }}
            />
          </div>
          {suggestions.length > 0 && (
            <div
              style={{
                position: 'absolute',
                top: '100%',
                left: 0,
                right: 0,
                background: 'var(--surface)',
                border: '1px solid var(--border)',
                borderRadius: 'var(--radius-sm)',
                zIndex: 50,
                boxShadow: 'var(--shadow-lg)',
              }}
            >
              {suggestions.map((t) => (
                <div
                  key={t.id}
                  onClick={() => addTag(t)}
                  style={{
                    padding: '10px 14px',
                    cursor: 'pointer',
                    display: 'flex',
                    alignItems: 'center',
                    gap: 8,
                    fontSize: 14,
                  }}
                  onMouseEnter={(e) => (e.currentTarget.style.background = 'var(--bg)')}
                  onMouseLeave={(e) => (e.currentTarget.style.background = 'transparent')}
                >
                  <TagBadge tag={t} />
                  <span className="text-muted">{t.usageCount} bài viết</span>
                </div>
              ))}
            </div>
          )}
          <div className="form-hint">Nhấn Enter để thêm tag. Tối đa 10 tags.</div>
        </div>

        <div style={{ display: 'flex', gap: 12, justifyContent: 'flex-end', paddingTop: 16, borderTop: '1px solid var(--border)' }}>
          <button className="btn btn-ghost" onClick={() => navigate('/forum')}>
            Hủy
          </button>
          <button className="btn btn-primary" onClick={handleSubmit} disabled={loading}>
            {loading ? 'Đang đăng...' : '📤 Đăng bài viết'}
          </button>
        </div>
      </div>

      {toasts.map((t, i) => (
        <div key={i} className={`toast toast-${t.type}`}>
          {t.message}
        </div>
      ))}
    </div>
  );
}

profile.__content:
import React, { useEffect, useState } from 'react';
import UserAvatar from '../components/common/UserAvatar';
import RoleBadge from '../components/common/RoleBadge';
import { forumService } from '../services/forumService';
import { userService } from '../services/userService';
import { authService } from '../services/authService';
import { useAuth } from '../hooks/useAuth';
import { addToast } from '../utils/toast';
import type { Post } from '../types';

type ProfileForm = {
  name: string;
  bio: string;
  email: string;
};

const ProfilePage: React.FC = () => {
  const { user: currentUser, loading } = useAuth();
  const [tab, setTab] = useState<'posts'|'saved'|'edit'|'password'>('posts');
  const [form, setForm] = useState<ProfileForm | null>(null);
  const [pwForm, setPwForm] = useState({ current:'', newpw:'', confirm:'' });
  const [saving, setSaving] = useState(false);
  const [savedPosts, setSavedPosts] = useState<Post[]>([]);
  const [savedLoading, setSavedLoading] = useState(false);

  const currentForm: ProfileForm = form ?? {
    name: currentUser?.name ?? '',
    bio: currentUser?.bio ?? '',
    email: currentUser?.email ?? '',
  };

  const handleFormChange = (field: keyof ProfileForm, value: string) => {
    setForm({ ...currentForm, [field]: value });
  };

  useEffect(() => {
    if (loading) return;
    if (!currentUser) {
      window.location.href = '/auth/login';
    }
  }, [currentUser, loading]);

  useEffect(() => {
    if (loading || !currentUser) return;
    const loadSaved = async () => {
      setSavedLoading(true);
      try {
        const posts = await forumService.getSavedPosts();
        setSavedPosts(posts);
      } catch {
        setSavedPosts([]);
      } finally {
        setSavedLoading(false);
      }
    };
    loadSaved();
  }, [currentUser, loading]);

  if (loading || !currentUser) return null;

  const handleSaveProfile = async () => {
    setSaving(true);
    try {
      await userService.updateProfile(currentForm);
      addToast('Đã cập nhật hồ sơ!', 'success');
    } catch { addToast('Không thể cập nhật', 'error'); }
    finally { setSaving(false); }
  };

  const handleChangePw = async () => {
    if (!pwForm.current) { addToast('Nhập mật khẩu hiện tại', 'error'); return; }
    if (pwForm.newpw.length < 6) { addToast('Mật khẩu mới ít nhất 6 ký tự', 'error'); return; }
    if (pwForm.newpw !== pwForm.confirm) { addToast('Mật khẩu xác nhận không khớp', 'error'); return; }
    setSaving(true);
    try {
      await authService.changePassword(pwForm.current, pwForm.newpw);
      setPwForm({ current:'', newpw:'', confirm:'' });
      addToast('Đã đổi mật khẩu thành công!', 'success');
    } catch { addToast('Mật khẩu hiện tại không đúng', 'error'); }
    finally { setSaving(false); }
  };

  const TABS: Array<{ key: 'posts'|'saved'|'edit'|'password'; label: string }> = [
    { key:'posts', label:'📝 Bài viết' },
    { key:'saved', label:'🔖 Đã lưu' },
    { key:'edit', label:'⚙️ Hồ sơ' },
    { key:'password', label:'🔒 Mật khẩu' },
  ];

  return (
    <div className="profile-page page-inner">
      {/* Profile header */}
      <div className="content-card profile-header-card">
        <div className="profile-avatar-wrapper">
          <UserAvatar user={currentUser} size="xl" />
          <div
            title="Thay đổi ảnh"
            className="profile-avatar-overlay"
            onClick={async () => {
              const input = document.createElement('input'); input.type='file'; input.accept='image/*';
              input.onchange = async () => {
                if (input.files?.[0]) {
                  try { await userService.uploadAvatar(input.files[0]); addToast('Đã cập nhật ảnh!', 'success'); }
                  catch { addToast('Không thể upload ảnh', 'error'); }
                }
              };
              input.click();
            }}>
            📷
          </div>
        </div>
        <div className="profile-details">
          <div className="profile-name">{currentUser.name}</div>
          <div className="profile-role-line"><RoleBadge role={currentUser.role} /></div>
          <div className="profile-email">{currentUser.email}</div>
          {currentUser.bio && <div className="profile-bio">{currentUser.bio}</div>}
          <div className="profile-metrics">
            {[{num:12,label:'Bài viết'},{num:48,label:'Bình luận'},{num:234,label:'Vote nhận'}].map((s,i) => (
              <div key={i} className="profile-stat">
                <div className="profile-stat-number">{s.num}</div>
                <div className="profile-stat-label">{s.label}</div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Tabs */}
      <div className="profile-tab-bar">
        {TABS.map(t => (
          <button key={t.key} onClick={() => setTab(t.key)} className={`admin-tab-btn${tab===t.key ? ' active' : ''}`}>
            {t.label}
          </button>
        ))}
      </div>

      {/* Tab: Posts */}
      {tab==='posts' && (
        <div className="content-card profile-section-card">
          <div className="profile-empty-state">
            <div className="profile-empty-icon">📝</div>
            <p>Bạn chưa đăng bài viết nào</p>
            <button onClick={() => { window.location.href = '/ask'; }} className="profile-action-btn profile-empty-cta">
              Đặt câu hỏi đầu tiên
            </button>
          </div>
        </div>
      )}

      {/* Tab: Saved */}
      {tab==='saved' && (
        <div className="content-card profile-section-card">
          {savedLoading ? (
            <div className="profile-empty-state">
              <div className="profile-empty-icon">⏳</div>
              <p>Đang tải bài viết đã lưu...</p>
            </div>
          ) : savedPosts.length > 0 ? (
            <div className="saved-post-grid">
              {savedPosts.map((post) => (
                <button key={post.id} className="saved-post-card" onClick={() => window.location.href = `/forum/${post.id}`}>
                  <div className="saved-post-title">{post.title}</div>
                  <div className="saved-post-meta">
                    <span>👤 {post.author.name}</span>
                    <span>💬 {post.commentCount ?? 0}</span>
                    <span>👁 {post.views ?? 0}</span>
                  </div>
                  <div className="saved-post-tag-row">
                    {post.tags.map((tag) => (
                      <span key={tag.id} className="saved-post-tag" style={{ background: tag.color ? `${tag.color}22` : 'var(--border)', color: tag.color || 'var(--text)' }}>{tag.name}</span>
                    ))}
                  </div>
                </button>
              ))}
            </div>
          ) : (
            <div className="profile-saved-empty">
              <div className="profile-empty-icon">🔖</div>
              <p>Chưa có bài viết nào được lưu</p>
            </div>
          )}
        </div>
      )}

      {/* Tab: Edit profile */}
      {tab==='edit' && (
        <div className="content-card profile-form-card">
          <div className="profile-form-title">Thông tin cá nhân</div>
          {[
            { key:'name' as const, label:'Tên đăng nhập', type:'text' },
            { key:'email' as const, label:'Email', type:'email' },
          ].map(field => (
            <div key={field.key} className="profile-field">
              <label className="form-label">{field.label}</label>
              <input type={field.type} value={currentForm[field.key]} onChange={e => handleFormChange(field.key, e.target.value)} className="form-input" />
            </div>
          ))}
          <div className="profile-field">
            <label className="form-label">Giới thiệu bản thân</label>
            <textarea value={currentForm.bio} onChange={e => handleFormChange('bio', e.target.value)} placeholder="Mô tả ngắn về bản thân, chuyên ngành, sở thích..."
              className="form-textarea" />
          </div>
          <button onClick={handleSaveProfile} disabled={saving} className="profile-action-btn">
            {saving ? 'Đang lưu...' : '💾 Lưu thay đổi'}
          </button>
        </div>
      )}

      {/* Tab: Password */}
      {tab==='password' && (
        <div className="content-card profile-form-card profile-form-sm">
          <div className="profile-form-title">Đổi mật khẩu</div>
          {[
            { key:'current' as const, label:'Mật khẩu hiện tại', placeholder:'Nhập mật khẩu hiện tại' },
            { key:'newpw' as const, label:'Mật khẩu mới', placeholder:'Ít nhất 6 ký tự' },
            { key:'confirm' as const, label:'Xác nhận mật khẩu mới', placeholder:'Nhập lại mật khẩu mới' },
          ].map(field => (
            <div key={field.key} className="profile-field">
              <label className="form-label">{field.label}</label>
              <input type="password" value={pwForm[field.key]} onChange={e => setPwForm(p => ({ ...p, [field.key]: e.target.value }))} placeholder={field.placeholder} className="form-input" />
            </div>
          ))}
          <button onClick={handleChangePw} disabled={saving} className="profile-action-btn">
            {saving ? 'Đang lưu...' : '🔒 Đổi mật khẩu'}
          </button>
        </div>
      )}
    </div>
  );
};

export default ProfilePage;

